import{z as d,x as A,o as t,c as p,q as r,j as s,D as o,d as n,s as E,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"DeepSeek 3FS 文件系统","description":"","frontmatter":{"title":"DeepSeek 3FS 文件系统","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deepseek-3fs.md","filePath":"llm/deepseek-3fs.md","lastUpdated":1791413859000}'),B={name:"llm/deepseek-3fs.md"};function S(c,e,D,h,u,F){const i=A("Mermaid");return t(),p("div",null,[e[2]||(e[2]=r('<h1 id="deepseek-3fs-文件系统" tabindex="-1">DeepSeek 3FS 文件系统 <a class="header-anchor" href="#deepseek-3fs-文件系统" aria-label="Permalink to &quot;DeepSeek 3FS 文件系统&quot;">​</a></h1><div class="epigraph"><p>把数千块 SSD 与数百条 RDMA 网卡收成一块位置无关的共享盘：训练按文件随机读样本，推理把 KVCache 卸到闪存，都不另学一套对象 API。</p><footer>—— DeepSeek 3FS README 与 docs/design_notes.md</footer></div><p>Fire-Flyer File System（3FS）是 DeepSeek 开源周放出的并行文件系统，面向训练数据准备、DataLoader、检查点与推理 KVCache。它不是「再做一个 POSIX 兼容层」那么简单：计算、元数据、存储拆开扩，数据面走 InfiniBand / RoCE 的 RDMA，一致性用 CRAQ（Chain Replication with Apportioned Queries）。仓库把四件套写死：集群管理器、元数据服务、存储服务、客户端。本篇钉这份设计笔记与 README 里的吞吐数字，不把未给出的单盘 IOPS 外推成合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AI 作业要的存储形态彼此打架。数据准备要目录树、原子改名、硬链接做轻量快照；DataLoader 要跨计算节点随机读未对齐的小样本，而不是先把数据集洗到本地盘；检查点要并行大块写；推理 KVCache 要吞吐高、容量远大于 DRAM，却仍希望命中后少做 prefill。对象存储用斜杠假装层级，搬目录与递归删除要应用自己扫键；本地 NVMe 快，但训练节点一换，缓存作废。3FS 要回答的是：在全闪加 RDMA 的机房里，能否用<strong>文件接口</strong>把这四类负载接到同一套位置无关的池上，并且读路径能吃满网卡。</p><p>FUSE 把远程文件系统伪装成本地盘，迁移成本低，但设计笔记把两条硬伤写清楚：用户态守护进程碰不到应用内存，要多一次拷贝；内核把请求丢进带自旋锁的共享队列，他们测到大约每秒 40 万次 4KiB 读就上不去。Linux 5.x 的 FUSE 还不支持同一文件并发写。训练里随机、未 4K 对齐的小读，会把 SSD 与 RDMA 的带宽浪费在这条内核路径上。</p><p><span class="marginnote">数字实例：40 万次/秒是什么概念——单次 4KiB 读如果走 FUSE 内核路径约 2.5 微秒就顶死了；而 RDMA 网卡本身能收发的请求高一个数量级，NVMe 盘也是。也就是说 40 万是「内核通道」的天花板，不是硬件的：换通道（USRBIO）而不是换盘，才能继续涨。</span></p><h3 id="位置无关与强一致同时要" tabindex="-1">位置无关与强一致同时要 <a class="header-anchor" href="#位置无关与强一致同时要" aria-label="Permalink to &quot;位置无关与强一致同时要&quot;">​</a></h3><p>分离式架构意味着客户端不应假设「数据在哪台机器上更快」。吞吐要随 SSD 数与客户–存储之间的对剖带宽线性涨，即使有盘故障。强一致则让应用不必自己做最终一致的 vis 逻辑。这两条通常互相拉扯：强一致容易把读钉在主副本上，打不满副本盘。CRAQ 的 write-all-read-any 正是为读多写少的全闪系统设计的。</p><p><span class="marginnote">3FS 的 KVCache 是「文件上的块」而不是引擎内部的分页槽。索引（token 与块的对应）要另做，且应常驻内存；假阳性命中会把错误 KV 喂进注意力。DeepSeek 在 issue 里写的原则是：尽力命中，不承诺命中率，未命中就重算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四个组件全部挂在 RDMA 网上。元数据与存储服务向集群管理器心跳；管理器处理成员变更、分发路由（链表）。管理器多实例部署，选主；配置通常放 ZooKeeper / etcd，生产里他们用与文件元数据同一套 KV 以减少依赖。文件的 open / create / rename 进元数据服务。元数据在 FoundationDB 里，事务是 SSI，所以元数据服务无状态，客户端可连任一实例，升级可滚动。</p><p>存储服务管本机若干 SSD，对外是 chunk store。文件切成等大 chunk，按复制链做 CRAQ：写进头、沿链传播，读可打链上任一干净副本。每个 SSD 上建多个 storage target，分别加入不同链，避免一块盘故障时流量全部砸到固定的两三个邻居。创建文件时，元数据按目录上的 chain table、chunk size、stripe size 做 round-robin 再 shuffle 选链；打开后客户端自己能算 chunk ID 与链，数据路径不再问 meta。</p><p><span class="marginnote">术语翻译：CRAQ（链式复制）像传纸条——写请求从链头传到链尾，人人都写完才算提交；读请求却可以找链上任何一个「抄完了」的成员要，不用排队找头。写全串行、读随便挑，正好匹配「写少读多」的 AI 数据负载，这也是它比「三副本随机写」类方案适合全闪存储的原因。</span></p><h3 id="usrbio-在-fuse-守护进程里开一条-uring-式旁路" tabindex="-1">USRBIO：在 FUSE 守护进程里开一条 uring 式旁路 <a class="header-anchor" href="#usrbio-在-fuse-守护进程里开一条-uring-式旁路" aria-label="Permalink to &quot;USRBIO：在 FUSE 守护进程里开一条 uring 式旁路&quot;">​</a></h3><p>他们没有写内核 VFS 模块——诊断难、升级要停所有用户。原生客户端做在 FUSE 守护进程里：元数据仍走 POSIX 的 open/stat，数据走异步零拷贝 API。两块共享结构模仿 <code>io_uring</code>：</p><ul><li><strong>Iov</strong>：大块共享内存，RDMA 注册由客户端代管；读进这块，写也先放这块。</li><li><strong>Ior</strong>：小环，用户入队、客户端出队；<code>io_depth</code> 控制批大小，多批并行。多线程应多环，共环要加锁。</li></ul><p>客户端线程从环取请求、攒批再打存储服务，把小读的 RPC 开销摊掉。性能关键路径（DataLoader、KVCache 拉块）应走 USRBIO；普通脚本可以继续挂 FUSE。基准应用仓库里的 fio USRBIO 引擎，而不是对本机 <code>read()</code> 计时。</p>',18)),(t(),s(l,null,{default:o(()=>[E(i,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20FUSE%5B%22FUSE%EF%BC%9Aopen%20%2F%20stat%22%5D%0A%20%20APP%20--%3E%20USB%5B%22USRBIO%EF%BC%9AIov%20%2F%20Ior%22%5D%0A%20%20FUSE%20--%3E%20META%5B%22%E6%97%A0%E7%8A%B6%E6%80%81%20Meta%20%2F%20FoundationDB%22%5D%0A%20%20USB%20--%3E%20STOR%5B%22Storage%20%2B%20CRAQ%20%E9%93%BE%22%5D%0A%20%20MGMT%5B%22Cluster%20Manager%22%5D%20--%3E%20META%0A%20%20MGMT%20--%3E%20STOR%0A%20%20STOR%20--%3E%20SSD%5B%22%E6%9C%AC%E6%9C%BA%20NVMe%20chunk%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[n("CRAQ 写路径：校验链版本 → RDMA Read 拉数据 → 在头上对 chunk 加锁串行化 → 读已提交版本、写出 pending（版本号 \\(u=v+1\\)）→ 非尾则转后继，尾则原子提交并回 ack，ack 沿链回头把 pending 提成 committed。读：只有 committed 就直接回；同时有 pending 时，他们的实现"),a("strong",null,"不"),n("像论文 CRAQ 那样去问尾节点版本，而是给客户端一个特殊状态，短等重试，或放宽读拿 pending。故障时管理器把掉线 target 挪到链尾并升版本；头会按新表继续往新后继转写，后继若尚未看到新表会拒，头重试直到对齐。")],-1)),e[5]||(e[5]=a("p",null,"恢复与正常流量重叠。归来的服务先等自己的 target 在链表里被标成 offline，再接受全 chunk 替换写，等于把前驱的状态流式拷过来。前驱 dump 双方 chunk 元数据再决定传哪些：只在一边、链版本更新、或 committed/pending 对不上的，才传。物理块按 64KiB–64MiB 的 11 档幂次分配，写走 copy-on-write，追加可原地接到块尾。元数据在 RocksDB，内存里另有 hashmap 缓存。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"文件长度在 inode 里，活跃写时只是最终一致：客户端默认每 5 秒上报最大写位置。close/fsync 才向存储查最后一块。生产 stripe 常取 200，小文件用 inode 里「可能用到的链数」提示，从 16 起倍增，避免每次去问满 200 条链。")],-1)),e[7]||(e[7]=a("p",null,"组件架构图回答「四件套怎么摆」；一次写如何变成人人可读的 committed 版本，是 CRAQ 链上的另一条时间线：",-1)),(t(),s(l,null,{default:o(()=>[E(i,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%86%99%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20H%5B%22%E9%93%BE%E5%A4%B4%EF%BC%9A%E6%A0%A1%E9%AA%8C%E7%89%88%E6%9C%AC%3Cbr%2F%3ERDMA%20%E6%8B%89%E6%95%B0%E6%8D%AE%EF%BC%8C%E5%86%99%E5%87%BA%20pending%20%E7%89%88%E6%9C%AC%22%5D%0A%20%20H%20--%3E%20M1%5B%22%E9%93%BE%E4%B8%AD%E6%88%90%E5%91%98%20A%EF%BC%9A%E8%BF%BD%E5%8A%A0%20pending%22%5D%0A%20%20M1%20--%3E%20T%5B%22%E9%93%BE%E5%B0%BE%EF%BC%9A%E5%8E%9F%E5%AD%90%E6%8F%90%E4%BA%A4%3Cbr%2F%3E%E5%9B%9E%20ack%22%5D%0A%20%20T%20--%3E%20ACK%5B%22ack%20%E6%B2%BF%E9%93%BE%E5%9B%9E%E5%A4%B4%E4%BC%A0%E6%92%AD%3Cbr%2F%3E%E5%90%84%E5%89%AF%E6%9C%AC%20pending%20%E6%8F%90%E6%88%90%20committed%22%5D%0A%20%20ACK%20--%3E%20R%5B%22%E6%AD%A4%E5%90%8E%E4%BB%BB%E6%84%8F%E6%88%90%E5%91%98%E9%83%BD%E5%8F%AF%E6%9C%8D%E5%8A%A1%E8%AF%BB%22%5D%0A%20%20R%20--%3E%20RD%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AF%BB%EF%BC%9A%E6%8C%91%E4%BB%BB%E4%B8%80%E5%B9%B2%E5%87%80%E5%89%AF%E6%9C%AC%3Cbr%2F%3E%E7%BB%95%E5%BC%80%E5%BF%99%E7%9A%84%E5%A4%B4%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=r('<p><span class="marginnote">为什么重要：如果读也必须打链头（最传统的主副本复制），几百个训练节点的小读会瞬间把头压垮，其余副本的盘全在围观。CRAQ 把读摊到全链，聚合带宽才能随 SSD 数量线性涨——「6.6 TiB/s」这种数字的前提就是读路径不经过任何单点。</span></p><h3 id="readme-里三组数字怎么读" tabindex="-1">README 里三组数字怎么读 <a class="header-anchor" href="#readme-里三组数字怎么读" aria-label="Permalink to &quot;README 里三组数字怎么读&quot;">​</a></h3><p>峰值读：180 存储节点，每节点 2×200Gbps IB、十六块 14TiB NVMe；500+ 客户端各 1×200Gbps。聚合读约 <strong>6.6 TiB/s</strong>，且当时有训练作业背景流量。GraySort：25 存储 + 50 计算，110.5 TiB、8192 分区，30 分 14 秒，平均 <strong>3.66 TiB/min</strong>。KVCache：客户端每节点 1×400Gbps，图上峰值读吞吐到 <strong>40 GiB/s</strong>（仓库说明这是某一时刻单客户端峰值，不同时刻峰值可能落在不同节点）。这些是他们集群上的应力与业务图，不是「任意 180 节点都能抄出 6.6」。规划时用自己的 NIC×盘数做屋顶线，再扣 CRAQ 复制与恢复期重定向。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>只读打开的 fd 不跟踪，因为训练启动会打开大量文件；删除已写打开的文件会等到写会话结束，并靠客户端存活探测清幽灵会话。这不是完整 POSIX「删已打开文件」语义。FUSE 路径不要拿去测 KVCache。<code>std::shuffle</code> 在 GCC 10/11 行为不同，二进制不兼容；编译必须钉 <code>-DSHUFFLE_METHOD</code>，旧集群跟当时的编译器走。</p><p>不要把 3FS 写成 Mooncake Store 的替代品。3FS 提供文件与 USRBIO；KV 的块键、前缀树、PD 交接仍要引擎或 LMCache 一类连接器。LMCache 文档写明：走 FUSE 的 FSConnector 吃不到 3FS 的带宽，要用 hf3fs 的 USRBIO 插件。假命中比未命中更糟，索引必须与模型版本、精度、RoPE 一起进键。</p><p><span class="marginnote">出处：<a href="https://github.com/deepseek-ai/3FS" target="_blank" rel="noreferrer">https://github.com/deepseek-ai/3FS</a> README（6.6 TiB/s、GraySort、KVCache 40 GiB/s）与 docs/design_notes.md（四组件、CRAQ、USRBIO、FoundationDB）。P 规格与 UsrbIo.md 是实现合同，升级集群前先对 shuffle 方法与链表版本。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>3FS 用分离架构 + RDMA + 文件接口，把数据准备、随机读样本、检查点、KVCache 接到同一闪存池。</li><li>元数据无状态、落 FoundationDB；数据按 chunk 做 CRAQ，读打任意干净副本。</li><li>热路径走 USRBIO（Iov/Ior），FUSE 只承担元数据与低门槛挂载。</li><li>公开数字：180 节点应力读约 6.6 TiB/s；GraySort 3.66 TiB/min；KVCache 客户端峰值约 40 GiB/s。</li><li>位置无关不等于无故障税：链表编排要让掉盘后的读摊到更多 SSD。</li><li>出处：DeepSeek 3FS 设计笔记与 README。</li></ul>',9))])}const R=d(B,[["render",S]]);export{m as __pageData,R as default};
